import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"A/B slots, install, and OTA updates","description":"","frontmatter":{},"headers":[],"relativePath":"manual/update-ota.md","filePath":"manual/update-ota.md"}'),d={name:"manual/update-ota.md"};function i(n,e,r,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="a-b-slots-install-and-ota-updates" tabindex="-1">A/B slots, install, and OTA updates <a class="header-anchor" href="#a-b-slots-install-and-ota-updates" aria-label="Permalink to &quot;A/B slots, install, and OTA updates&quot;">​</a></h1><h2 id="the-update-wizard" tabindex="-1">The update wizard <a class="header-anchor" href="#the-update-wizard" aria-label="Permalink to &quot;The update wizard&quot;">​</a></h2><p>The intended path is the wizard - it walks the whole &quot;bring this machine to the newest version&quot; intent in five checked steps:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; update</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Step</th><th>What it does</th><th>What it can fix</th></tr></thead><tbody><tr><td>1/5 network</td><td>reads the IP status</td><td>a 0.0.0.0 address offers a DHCP fix, then rechecks</td></tr><tr><td>2/5 A/B disk</td><td>reads <code>update status</code></td><td>absent disk: shows <code>lsblk</code>, walks you through a double-confirmed <code>abdisk &lt;dev&gt;</code>, rechecks</td></tr><tr><td>3/5 DNS</td><td>resolves the update host parsed from the live <code>config get update_url</code></td><td>-</td></tr><tr><td>4/5 check</td><td><code>checkupdate</code></td><td>up-to-date ends the wizard OK</td></tr><tr><td>5/5 install</td><td>confirmed online update</td><td>confirmed reboot into the new slot</td></tr></tbody></table><p>Every step prints its verdict (<code>[OK]</code> / <code>[!!]</code>) and aborts cleanly when its precondition cannot be repaired - nothing destructive runs without a bare <code>y</code>.</p><h2 id="the-a-b-scheme" tabindex="-1">The A/B scheme <a class="header-anchor" href="#the-a-b-scheme" aria-label="Permalink to &quot;The A/B scheme&quot;">​</a></h2><p>The selfhost service maintains two slots (A and B) plus a boot flag:</p><ul><li>GRUB reads the flag and boots the active slot; the menu offers force-slot entries as the manual override.</li><li>An update installs onto the <em>inactive</em> slot while you keep running.</li><li>The next boot flips to the updated slot; <code>update rollback</code> flips back if you reject it.</li></ul><p><code>update status</code> shows the whole picture: current version, current boot slot, next boot, available update, online-update flag, and whether the A/B disk is present.</p><h2 id="installing-to-a-disk" tabindex="-1">Installing to a disk <a class="header-anchor" href="#installing-to-a-disk" aria-label="Permalink to &quot;Installing to a disk&quot;">​</a></h2><p>From a running ISO boot:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; dskstat                (pick a target disk, e.g. hd0)</span></span>
<span class="line"><span>ush&gt; install hd0            (partition + copy the running kernel +</span></span>
<span class="line"><span>                             GRUB boot files + /etc volume)</span></span></code></pre></div><p>or through the wizard: <code>disk-tool</code> -&gt; A/B update disk manager -&gt; create (the device name is asked, retyped and confirmed).</p><p><code>install</code> copies the multiboot2 module <code>self</code> - literally the kernel ELF that is running right now - onto the disk, so the installed system always matches its installer. <code>abdisk &lt;dev&gt;</code> does the same shaped as an A/B update disk (two slots + flags; destroys data). <code>abcfg</code> shows the exact grub.cfg files those commands write.</p><h2 id="checking-for-updates" tabindex="-1">Checking for updates <a class="header-anchor" href="#checking-for-updates" aria-label="Permalink to &quot;Checking for updates&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; checkupdate            (reads the update URL from /etc/opencube.conf</span></span>
<span class="line"><span>                             - http or https - and parses the manifest)</span></span>
<span class="line"><span>ush&gt; config get update_url  (the configuration key it uses)</span></span></code></pre></div><p>The manifest is the website&#39;s <code>update.json</code>: version, build, package URL, package SHA256, size. The build comparison is numeric (BUG-0347), so a rebuild with a higher build number wins even when the version string is equal.</p><h2 id="update-sources-and-mirrors" tabindex="-1">Update sources and mirrors <a class="header-anchor" href="#update-sources-and-mirrors" aria-label="Permalink to &quot;Update sources and mirrors&quot;">​</a></h2><p>The update source is the <code>update_url</code> configuration key - a plain HTTPS URL to a <code>update.json</code> manifest. The wizard&#39;s step 3 reads the live value (<code>config get update_url</code>) and resolves its host before anything touches the network. To point a machine at a different source, use the ordinary config writer:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; config set update_url &lt;url&gt;</span></span></code></pre></div><p>Known-good values (they all serve the <em>same</em> manifest from the gh-pages branch, so pick the one your network reaches best):</p><table tabindex="0"><thead><tr><th>Source</th><th>URL</th></tr></thead><tbody><tr><td>Official (GitHub Pages)</td><td><code>https://cubestudio-dev.github.io/OpenCubeOS/update.json</code></td></tr><tr><td>GitHub raw mirror</td><td><code>https://raw.githubusercontent.com/cubestudio-dev/OpenCubeOS/gh-pages/update.json</code></td></tr><tr><td>jsDelivr CDN mirror</td><td><code>https://cdn.jsdelivr.net/gh/cubestudio-dev/OpenCubeOS@gh-pages/update.json</code></td></tr></tbody></table><p>A custom value works too - it must start with <code>http://</code> or <code>https://</code> and point at a manifest with the same shape (<code>checkupdate</code> prints a parse error otherwise). Mirrors matter when one host is blocked or slow from your network: the manifest carries absolute package URLs, so after switching the source the package download follows the manifest&#39;s own <code>url</code> field.</p><h2 id="applying-an-update" tabindex="-1">Applying an update <a class="header-anchor" href="#applying-an-update" aria-label="Permalink to &quot;Applying an update&quot;">​</a></h2><p>The online flow (what the wizard&#39;s step 5 runs after confirmation, and what bare <code>update direct</code> does):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; update direct          check -&gt; download -&gt; verify -&gt; install</span></span>
<span class="line"><span>ush&gt; reboot                 boot the updated slot</span></span></code></pre></div><p>Offline / air-gapped machines:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; update --local /path/to/package.tar.gz</span></span></code></pre></div><p>The OTA package (<code>opencube-&lt;version&gt;-update.tar.gz</code>) carries the new kernel ELF plus a manifest. Verification is cryptographic: the manifest SHA256 is enforced inside the install - a package that fails it is refused.</p><p>Large packages never stress memory: the downloader streams the package to disk in 4 KiB chunks (<code>DL_CHUNK</code>, <code>ocos/services/selfhost/src/svc_selfhost_ab.c</code> - <code>ota_update_download</code>), so an update works for packages far larger than RAM; only the SHA256 state and one chunk buffer ever live in memory.</p><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>If a slot misbehaves after a flip:</p><ol><li>Pick the other slot from the GRUB menu (force entry), or</li><li><code>ush&gt; update rollback</code> from inside a running system.</li></ol><p><code>ab_partition_test</code> exercises slot discovery, flags and slot switching on a scratch disk without touching your real boot disk.</p><h2 id="update-related-commands" tabindex="-1">Update-related commands <a class="header-anchor" href="#update-related-commands" aria-label="Permalink to &quot;Update-related commands&quot;">​</a></h2><p><code>checkupdate</code>, <code>update</code> (wizard + the chain above), <code>rollback</code>, <code>config</code> (update URL keys), <code>abdisk</code>, <code>abcfg</code>, <code>ab_partition_test</code>. All of them are also classic ops of the <code>update</code> / <code>disk-tool</code> apps. Full list with one page each: <a href="./commands/">commands index</a> - &quot;OTA updates and A/B slots&quot; domain.</p><h2 id="internals" tabindex="-1">Internals <a class="header-anchor" href="#internals" aria-label="Permalink to &quot;Internals&quot;">​</a></h2><p>For how the flags are stored, how install stages the inactive slot, and the boot-flag handshake with GRUB, see <a href="./../internals/ota-ab.html">../internals/ota-ab.md</a>.</p>`,39)])])}const g=t(d,[["render",i]]);export{u as __pageData,g as default};
